    12	public final class App {
    13	    private App() {}
    14	
    15	    public static void main(String[] args) {
    16	        Database database = new Database(
    17	                required("DB_URL"), System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
    18	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
    19	        int port = System.getenv("PORT") == null ? 7070 : Integer.parseInt(System.getenv("PORT"));
    20	
    21	        Javalin app = build(database, testMode);
    22	        app.start(port);
    23	    }
    24	
    25	    public static Javalin build(Database database, boolean testMode) {
    26	        database.initialize();
    27	        ReservationRepository reservations = new ReservationRepository(database);
    28	        JdbcMessageStore messages = new JdbcMessageStore(database);
    29	        MessageSender sender = Installation.marealta(messages, testMode);
    30	        ReservationService service = new ReservationService(reservations, sender);
    31	        return new WebApp(service, reservations, messages).create();
    32	    }
