     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.ApiException;
     4	import br.com.marealta.domain.NewReservation;
     5	import br.com.marealta.domain.RatePlan;
     6	import com.fasterxml.jackson.core.JsonProcessingException;
     7	import com.fasterxml.jackson.databind.JsonNode;
     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeParseException;
    12	
    13	/** Lê e confere o corpo do POST /reservations. */
    14	final class ReservationRequest {
    15	    private ReservationRequest() {}
    16	
    17	    static NewReservation parse(ObjectMapper mapper, String body) {
    18	        JsonNode json;
    19	        try {
    20	            json = mapper.readTree(body);
    21	        } catch (JsonProcessingException e) {
    22	            throw ApiException.invalidRequest("O corpo não é um JSON válido");
    23	        }
    24	        if (json == null || !json.isObject()) {
    25	            throw ApiException.invalidRequest("O corpo precisa ser um objeto JSON");
    26	        }
    27	        return new NewReservation(
    28	                integer(json, "roomNumber"),
    29	                text(json, "guestName"),
    30	                text(json, "guestEmail"),
    31	                text(json, "guestCpf"),
    32	                date(json, "checkIn"),
    33	                date(json, "checkOut"),
    34	                integer(json, "guests"),
    35	                ratePlan(json));
    36	    }
    37	
    38	    private static String text(JsonNode json, String field) {
    39	        JsonNode node = json.get(field);
    40	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    41	            throw ApiException.invalidRequest("Campo '" + field + "' ausente ou inválido");
    42	        }
    43	        return node.asText();
    44	    }
    45	
    46	    private static int integer(JsonNode json, String field) {
    47	        JsonNode node = json.get(field);
    48	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    49	            throw ApiException.invalidRequest("Campo '" + field + "' ausente ou inválido");
    50	        }
    51	        return node.asInt();
    52	    }
    53	
    54	    private static LocalDate date(JsonNode json, String field) {
    55	        try {
    56	            return LocalDate.parse(text(json, field));
    57	        } catch (DateTimeParseException e) {
    58	            throw ApiException.invalidRequest("Campo '" + field + "' deve estar no formato aaaa-mm-dd");
    59	        }
    60	    }
    61	
    62	    private static RatePlan ratePlan(JsonNode json) {
    63	        try {
    64	            return RatePlan.valueOf(text(json, "ratePlan"));
    65	        } catch (IllegalArgumentException e) {
    66	            throw ApiException.invalidRequest("Campo 'ratePlan' deve ser STANDARD ou NON_REFUNDABLE");
    67	        }
    68	    }
    69	}
