     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.ApiException;
     4	import br.com.marealta.domain.Reservation;
     5	import br.com.marealta.domain.RoomCatalog;
     6	import br.com.marealta.messaging.MessageStore;
     7	import br.com.marealta.persistence.ReservationRepository;
     8	import br.com.marealta.report.OccupancyReport;
     9	import br.com.marealta.report.RevenueReport;
    10	import br.com.marealta.service.ReservationService;
    11	import com.fasterxml.jackson.core.JsonProcessingException;
    12	import com.fasterxml.jackson.databind.ObjectMapper;
    13	import io.javalin.Javalin;
    14	import io.javalin.http.Context;
    15	
    16	import java.time.LocalDate;
    17	import java.time.YearMonth;
    18	import java.time.format.DateTimeParseException;
    19	import java.util.LinkedHashMap;
    20	import java.util.Map;
    21	import java.util.function.Function;
    22	
    23	public final class WebApp {
    24	    private final ObjectMapper mapper = new ObjectMapper();
    25	    private final ReservationService service;
    26	    private final ReservationRepository reservations;
    27	    private final MessageStore messages;
    28	
    29	    public WebApp(ReservationService service, ReservationRepository reservations, MessageStore messages) {
    30	        this.service = service;
    31	        this.reservations = reservations;
    32	        this.messages = messages;
    33	    }
    34	
    35	    public Javalin create() {
    36	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    37	
    38	        app.get("/rooms", ctx -> json(ctx, 200, RoomCatalog.all().stream().map(Views::room).toList()));
    39	
    40	        app.post("/reservations", ctx -> json(ctx, 201,
    41	                Views.reservation(service.create(ReservationRequest.parse(mapper, ctx.body())))));
    42	        app.get("/reservations/{id}", ctx -> json(ctx, 200, Views.reservation(service.get(id(ctx)))));
    43	        app.post("/reservations/{id}/confirmation", reservationAction(service::confirm));
    44	        app.post("/reservations/{id}/cancellation", reservationAction(service::cancel));
    45	        app.post("/reservations/{id}/check-in", reservationAction(service::checkIn));
    46	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, Views.receipt(service.checkOut(id(ctx)))));
    47	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, Views.receipt(service.document(id(ctx)))));
    48	
    49	        app.get("/messages", ctx -> json(ctx, 200, messages.all().stream().map(Views::message).toList()));
    50	
    51	        app.get("/reports/occupancy", ctx -> {
    52	            LocalDate night = parseDate(ctx.queryParam("date"));
    53	            csv(ctx, OccupancyReport.render(night, reservations.findOccupying(night)));
    54	        });
    55	        app.get("/reports/revenue", ctx -> {
    56	            YearMonth month = parseMonth(ctx.queryParam("month"));
    57	            csv(ctx, RevenueReport.render(
    58	                    reservations.findCheckingInBetween(month.atDay(1), month.plusMonths(1).atDay(1))));
    59	        });
    60	
    61	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    62	        app.exception(Exception.class, (e, ctx) -> {
    63	            e.printStackTrace();
    64	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    65	        });
    66	        return app;
    67	    }
    68	
    69	    private io.javalin.http.Handler reservationAction(Function<Long, Reservation> action) {
    70	        return ctx -> json(ctx, 200, Views.reservation(action.apply(id(ctx))));
    71	    }
    72	
    73	    private static long id(Context ctx) {
    74	        try {
    75	            return Long.parseLong(ctx.pathParam("id"));
    76	        } catch (NumberFormatException e) {
    77	            throw ApiException.reservationNotFound();
    78	        }
    79	    }
    80	
    81	    private static LocalDate parseDate(String value) {
    82	        try {
    83	            return LocalDate.parse(value);
    84	        } catch (DateTimeParseException | NullPointerException e) {
    85	            throw ApiException.invalidRequest("Parâmetro 'date' deve estar no formato aaaa-mm-dd");
    86	        }
    87	    }
    88	
    89	    private static YearMonth parseMonth(String value) {
    90	        try {
    91	            return YearMonth.parse(value);
    92	        } catch (DateTimeParseException | NullPointerException e) {
    93	            throw ApiException.invalidRequest("Parâmetro 'month' deve estar no formato aaaa-mm");
    94	        }
    95	    }
    96	
    97	    private void error(Context ctx, int status, String code, String message) {
    98	        Map<String, Object> body = new LinkedHashMap<>();
    99	        body.put("error", code);
   100	        body.put("message", message);
   101	        json(ctx, status, body);
   102	    }
   103	
   104	    private void json(Context ctx, int status, Object body) {
   105	        try {
   106	            ctx.status(status).contentType("application/json").result(mapper.writeValueAsString(body));
   107	        } catch (JsonProcessingException e) {
   108	            throw new IllegalStateException(e);
   109	        }
   110	    }
   111	
   112	    private static void csv(Context ctx, String body) {
   113	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
   114	    }
   115	}
=== src/main/java/br/com/marealta/service/ReservationService.java
     1	package br.com.marealta.service;
     2	
     3	import br.com.marealta.domain.ApiException;
     4	import br.com.marealta.domain.NewReservation;
     5	import br.com.marealta.domain.Receipt;
     6	import br.com.marealta.domain.Reservation;
     7	import br.com.marealta.domain.Room;
     8	import br.com.marealta.domain.RoomCatalog;
     9	import br.com.marealta.messaging.Message;
    10	import br.com.marealta.messaging.MessageSender;
    11	import br.com.marealta.persistence.ReservationRepository;
    12	
    13	public final class ReservationService {
    14	    private static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    15	
    16	    private final ReservationRepository reservations;
    17	    private final MessageSender sender;
    18	
    19	    public ReservationService(ReservationRepository reservations, MessageSender sender) {
    20	        this.reservations = reservations;
    21	        this.sender = sender;
    22	    }
    23	
    24	    public synchronized Reservation create(NewReservation request) {
    25	        Room room = RoomCatalog.find(request.roomNumber())
    26	                .orElseThrow(() -> ApiException.roomNotFound(request.roomNumber()));
    27	        if (request.guests() > room.capacity()) {
    28	            throw ApiException.capacityExceeded(room.capacity());
    29	        }
    30	        Reservation reservation = Reservation.pending(room, request);
    31	        if (!reservations.insertIfAvailable(reservation)) {
    32	            throw ApiException.roomUnavailable();
    33	        }
    34	        return reservation;
    35	    }
    36	
    37	    public Reservation get(long id) {
    38	        return reservations.find(id).orElseThrow(ApiException::reservationNotFound);
    39	    }
    40	
    41	    public synchronized Reservation confirm(long id) {
    42	        Reservation reservation = get(id);
    43	        reservation.confirm();
    44	        reservations.update(reservation);
    45	        sender.send(confirmationMessage(reservation));
    46	        return reservation;
    47	    }
    48	
    49	    public synchronized Reservation cancel(long id) {
    50	        Reservation reservation = get(id);
    51	        reservation.cancel();
    52	        reservations.update(reservation);
    53	        return reservation;
    54	    }
    55	
    56	    public synchronized Reservation checkIn(long id) {
    57	        Reservation reservation = get(id);
    58	        reservation.registerCheckIn();
    59	        reservations.update(reservation);
    60	        return reservation;
    61	    }
    62	
    63	    public synchronized Receipt checkOut(long id) {
    64	        Reservation reservation = get(id);
    65	        reservation.registerCheckOut();
    66	        reservations.update(reservation);
    67	        return receiptOf(reservation);
    68	    }
    69	
    70	    /** Segunda via: só existe para reserva paga. */
    71	    public Receipt document(long id) {
    72	        Reservation reservation = get(id);
    73	        reservation.requirePaid();
    74	        return receiptOf(reservation);
    75	    }
    76	
    77	    private static Receipt receiptOf(Reservation reservation) {
    78	        return Receipt.of(reservation, RoomCatalog.find(reservation.roomNumber()).orElseThrow());
    79	    }
    80	
    81	    private static Message confirmationMessage(Reservation reservation) {
    82	        String body = "Olá, " + reservation.guestName() + "!\n\n"
    83	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    84	                + receiptOf(reservation).toText() + "\n\n"
    85	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    86	                + "Até breve!";
    87	        return Message.email(reservation.guestEmail(), CONFIRMATION_SUBJECT, body);
    88	    }
    89	}

