    40	        app.post("/reservations", ctx -> json(ctx, 201,
    41	                Views.reservation(service.create(ReservationRequest.parse(mapper, ctx.body())))));
    42	        app.get("/reservations/{id}", ctx -> json(ctx, 200, Views.reservation(service.get(id(ctx)))));
    43	        app.post("/reservations/{id}/confirmation", reservationAction(service::confirm));
    44	        app.post("/reservations/{id}/cancellation", reservationAction(service::cancel));
    45	        app.post("/reservations/{id}/check-in", reservationAction(service::checkIn));
    46	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, Views.receipt(service.checkOut(id(ctx)))));
