     1	package br.com.marealta.service;
     2	
     3	import br.com.marealta.domain.ApiException;
     4	import br.com.marealta.domain.NewReservation;
     5	import br.com.marealta.domain.Receipt;
     6	import br.com.marealta.domain.Reservation;
     7	import br.com.marealta.domain.Room;
     8	import br.com.marealta.domain.RoomCatalog;
     9	import br.com.marealta.messaging.Message;
    10	import br.com.marealta.messaging.MessageSender;
    11	import br.com.marealta.persistence.ReservationRepository;
    12	
    13	public final class ReservationService {
    14	    private static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    15	
    16	    private final ReservationRepository reservations;
    17	    private final MessageSender sender;
    18	
    19	    public ReservationService(ReservationRepository reservations, MessageSender sender) {
    20	        this.reservations = reservations;
    21	        this.sender = sender;
    22	    }
    23	
    24	    public synchronized Reservation create(NewReservation request) {
    25	        Room room = RoomCatalog.find(request.roomNumber())
    26	                .orElseThrow(() -> ApiException.roomNotFound(request.roomNumber()));
    27	        if (request.guests() > room.capacity()) {
    28	            throw ApiException.capacityExceeded(room.capacity());
    29	        }
    30	        Reservation reservation = Reservation.pending(room, request);
    31	        if (!reservations.insertIfAvailable(reservation)) {
    32	            throw ApiException.roomUnavailable();
    33	        }
    34	        return reservation;
    35	    }
    36	
    37	    public Reservation get(long id) {
    38	        return reservations.find(id).orElseThrow(ApiException::reservationNotFound);
    39	    }
    40	
    41	    public synchronized Reservation confirm(long id) {
    42	        Reservation reservation = get(id);
    43	        reservation.confirm();
    44	        reservations.update(reservation);
    45	        sender.send(confirmationMessage(reservation));
    46	        return reservation;
    47	    }
    48	
    49	    public synchronized Reservation cancel(long id) {
    50	        Reservation reservation = get(id);
    51	        reservation.cancel();
    52	        reservations.update(reservation);
    53	        return reservation;
    54	    }
    55	
    56	    public synchronized Reservation checkIn(long id) {
    57	        Reservation reservation = get(id);
    58	        reservation.registerCheckIn();
    59	        reservations.update(reservation);
    60	        return reservation;
    61	    }
    62	
    63	    public synchronized Receipt checkOut(long id) {
    64	        Reservation reservation = get(id);
    65	        reservation.registerCheckOut();
    66	        reservations.update(reservation);
    67	        return receiptOf(reservation);
    68	    }
    69	
    70	    /** Segunda via: só existe para reserva paga. */
    71	    public Receipt document(long id) {
    72	        Reservation reservation = get(id);
    73	        reservation.requirePaid();
    74	        return receiptOf(reservation);
    75	    }
    76	
    77	    private static Receipt receiptOf(Reservation reservation) {
    78	        return Receipt.of(reservation, RoomCatalog.find(reservation.roomNumber()).orElseThrow());
    79	    }
    80	
    81	    private static Message confirmationMessage(Reservation reservation) {
    82	        String body = "Olá, " + reservation.guestName() + "!\n\n"
    83	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    84	                + receiptOf(reservation).toText() + "\n\n"
    85	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    86	                + "Até breve!";
    87	        return Message.email(reservation.guestEmail(), CONFIRMATION_SUBJECT, body);
    88	    }
    89	}

