     3	public final class EmailAddress {
     4	    private EmailAddress() {}
     5	
     6	    /** Um único @, algo antes dele e, depois, um nome com pelo menos um ponto no meio. */
     7	    public static boolean isValid(String address) {
     8	        if (address == null) return false;
     9	        int at = address.indexOf('@');
    10	        if (at < 1 || at != address.lastIndexOf('@')) return false;
    11	        String domain = address.substring(at + 1);
    12	        return hasInnerDot(domain);
    13	    }
