     1	package br.com.marealta.messaging;
     2	
     3	import java.util.List;
     4	
     5	public final class MessagePipeline {
     6	    private MessagePipeline() {}
     7	
     8	    /**
     9	     * Monta o envio: parte do envio real e embrulha com cada regra que vale no modo atual,
    10	     * na ordem da lista (a primeira fica mais por dentro, a última é a primeira a ver a mensagem).
    11	     */
    12	    public static MessageSender assemble(MessageSender base, List<SendingRule> rules, boolean testMode) {
    13	        MessageSender sender = base;
    14	        for (SendingRule rule : rules) {
    15	            if (rule.scope().appliesTo(testMode)) {
    16	                sender = rule.wrapper().apply(sender);
    17	            }
    18	        }
