     1	package br.com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	import java.time.temporal.ChronoUnit;
     7	
     8	public final class Pricing {
     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    10	
    11	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    12	
    13	    private Pricing() {}
    14	
    15	    /** Alta temporada: de 15 de dezembro ao fim de fevereiro e todo o mês de julho. */
    16	    public static boolean isHighSeason(LocalDate night) {
    17	        Month month = night.getMonth();
    18	        return month == Month.JULY
    19	                || month == Month.JANUARY
    20	                || month == Month.FEBRUARY
    21	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    22	    }
    23	
    24	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    25	        BigDecimal rate = room.nightlyRate();
    26	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : Money.round(rate);
    27	    }
    28	
    29	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    30	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    31	        BigDecimal subtotal = Money.ZERO;
    32	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    33	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    34	        }
    35	        BigDecimal discount = plan.discountOn(subtotal);
    36	        BigDecimal total = Money.round(subtotal.subtract(discount));
    37	        return new Quote(nights, subtotal, discount, total);
    38	    }
    39	}
