    26	
    27	    /** Grava a reserva se o quarto estiver livre em todas as noites; devolve false se não estiver. */
    28	    public boolean insertIfAvailable(Reservation r) {
    29	        try (Connection c = database.open()) {
    30	            c.setAutoCommit(false);
    31	            try {
    32	                try (PreparedStatement lock = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    33	                    lock.setLong(1, r.roomNumber());
    34	                    lock.execute();
    35	                }
    36	                try (PreparedStatement overlap = c.prepareStatement(
    37	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED'"
    38	                                + " AND check_in < ? AND check_out > ?")) {
    39	                    overlap.setInt(1, r.roomNumber());
    40	                    overlap.setObject(2, r.checkOut());
    41	                    overlap.setObject(3, r.checkIn());
    42	                    try (ResultSet rs = overlap.executeQuery()) {
    43	                        if (rs.next()) {
    44	                            c.rollback();
    45	                            return false;
    46	                        }
    47	                    }
    48	                }
    49	                try (PreparedStatement insert = c.prepareStatement(
    50	                        "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in,"
    51	                                + " check_out, guests, rate_plan, nights, subtotal, discount, total, status,"
    52	                                + " amount_paid, refund) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
    53	                        Statement.RETURN_GENERATED_KEYS)) {
    54	                    insert.setInt(1, r.roomNumber());
    55	                    insert.setString(2, r.guestName());
    56	                    insert.setString(3, r.guestEmail());
    57	                    insert.setString(4, r.guestCpf());
    58	                    insert.setObject(5, r.checkIn());
    59	                    insert.setObject(6, r.checkOut());
    60	                    insert.setInt(7, r.guests());
    61	                    insert.setString(8, r.ratePlan().name());
    62	                    insert.setInt(9, r.nights());
    63	                    insert.setBigDecimal(10, r.subtotal());
    64	                    insert.setBigDecimal(11, r.discount());
    65	                    insert.setBigDecimal(12, r.total());
    66	                    insert.setString(13, r.status().name());
    67	                    insert.setBigDecimal(14, r.amountPaid());
    68	                    insert.setBigDecimal(15, r.refund());
    69	                    insert.executeUpdate();
    70	                    try (ResultSet keys = insert.getGeneratedKeys()) {
    71	                        keys.next();
    72	                        r.assignId(keys.getLong(1));
    73	                    }
    74	                }
    75	                c.commit();
    76	                return true;
    77	            } catch (SQLException e) {
    78	                c.rollback();
    79	                throw e;
    80	            }
    81	        } catch (SQLException e) {
    82	            throw new IllegalStateException(e);
    83	        }
    84	    }
