    95	            ps.setString(1, r.status().name());
    96	            ps.setBigDecimal(2, r.amountPaid());
    97	            ps.setBigDecimal(3, r.refund());
    98	            ps.setLong(4, r.id());
    99	            ps.executeUpdate();
   100	        } catch (SQLException e) {
   101	            throw new IllegalStateException(e);
   102	        }
   103	    }
   104	
   105	    /** Reservas que ocupam um quarto na noite indicada (entra nela, não sai nela), qualquer situação. */
   106	    public List<Reservation> findOccupying(LocalDate night) {
   107	        return query("SELECT " + COLUMNS + " FROM reservations WHERE check_in <= ? AND check_out > ? ORDER BY id",
   108	                ps -> {
   109	                    ps.setObject(1, night);
   110	                    ps.setObject(2, night);
   111	                });
   112	    }
   113	
   114	    /** Reservas com entrada no intervalo [from, until). */
   115	    public List<Reservation> findCheckingInBetween(LocalDate from, LocalDate until) {
   116	        return query("SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? ORDER BY id",
   117	                ps -> {
   118	                    ps.setObject(1, from);
   119	                    ps.setObject(2, until);
   120	                });
   121	    }
   122	
   123	    private interface Binder { void bind(PreparedStatement ps) throws SQLException; }
   124	
   125	    private List<Reservation> query(String sql, Binder binder) {
   126	        try (Connection c = database.open(); PreparedStatement ps = c.prepareStatement(sql)) {
   127	            binder.bind(ps);
   128	            try (ResultSet rs = ps.executeQuery()) {
   129	                List<Reservation> result = new ArrayList<>();
   130	                while (rs.next()) result.add(read(rs));
   131	                return result;
   132	            }
   133	        } catch (SQLException e) {
   134	            throw new IllegalStateException(e);
   135	        }
   136	    }
   137	
   138	    private static Reservation read(ResultSet rs) throws SQLException {
   139	        BigDecimal refund = rs.getBigDecimal("refund");
   140	        Pricing.Quote quote = new Pricing.Quote(rs.getInt("nights"), rs.getBigDecimal("subtotal"),
   141	                rs.getBigDecimal("discount"), rs.getBigDecimal("total"));
   142	        return new Reservation(rs.getLong("id"), rs.getInt("room_number"), rs.getString("guest_name"),
   143	                rs.getString("guest_email"), rs.getString("guest_cpf"),
   144	                rs.getObject("check_in", LocalDate.class), rs.getObject("check_out", LocalDate.class),
   145	                rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")), quote,
   146	                ReservationStatus.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"), refund);
   147	    }
