    23	                    .append(r.id()).append(',')
    24	                    .append(r.checkIn()).append(',')
    25	                    .append(r.checkOut()).append('\n');
    26	        }
    27	        long rooms = occupying.stream().map(Reservation::roomNumber).distinct().count();
