103	class DomainTest {
104	    private static final Room STANDARD = RoomCatalog.find(101).orElseThrow();
105	    private static final Room DELUXE = RoomCatalog.find(201).orElseThrow();
106	
107	    private static NewReservation request(Room room, String in, String out, RatePlan plan) {
108	        return new NewReservation(room.number(), "Carla Dias", "carla@example.com", "11122233344",
109	                LocalDate.parse(in), LocalDate.parse(out), 2, plan);
110	    }
111	
112	    @Test
113	    void highSeasonNightsCostTwentyPercentMore() {
114	        Pricing.Quote quote = Pricing.quote(STANDARD, LocalDate.parse("2027-07-10"), LocalDate.parse("2027-07-12"), RatePlan.STANDARD);
115	        assertEquals(new BigDecimal("599.76"), quote.total());
116	        assertEquals(2, quote.nights());
