118	
119	    @Test
120	    void seasonBoundaries() {
121	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-12-14")));
122	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2027-12-15")));
123	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2028-02-29")));
124	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2028-03-01")));
125	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-06-30")));
126	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-08-01")));
127	    }
