129	    @Test
130	    void nonRefundableGivesFifteenPercentOffRoundedHalfEven() {
131	        Pricing.Quote quote = Pricing.quote(DELUXE, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), RatePlan.NON_REFUNDABLE);
132	        assertEquals(new BigDecimal("779.80"), quote.subtotal());
133	        assertEquals(new BigDecimal("116.97"), quote.discount());
134	        assertEquals(new BigDecimal("662.83"), quote.total());
