162	    @Test
163	    void lifecycleAndRefunds() {
164	        Reservation r = Reservation.pending(STANDARD, request(STANDARD, "2027-03-10", "2027-03-12", RatePlan.STANDARD));
165	        assertThrows(ApiException.class, r::registerCheckIn);
