  3	import br.com.marealta.persistence.Database;
  4	import com.fasterxml.jackson.databind.JsonNode;
  5	import com.fasterxml.jackson.databind.ObjectMapper;
  6	import io.javalin.Javalin;
  7	import org.junit.jupiter.api.AfterAll;
  8	import org.junit.jupiter.api.Assumptions;
  9	import org.junit.jupiter.api.BeforeAll;
 10	import org.junit.jupiter.api.Test;
 11	
 12	import java.net.URI;
 13	import java.net.http.HttpClient;
 14	import java.net.http.HttpRequest;
 15	import java.net.http.HttpResponse;
 16	import java.sql.Connection;
 17	import java.sql.DriverManager;
 18	import java.sql.Statement;
 19	
 20	import static org.junit.jupiter.api.Assertions.*;
 21	
 22	/** Testa a API de ponta a ponta num schema descartável do PostgreSQL; é pulado se não houver banco. */
 23	class ApiTest {
 24	    private static final ObjectMapper JSON = new ObjectMapper().enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
 25	    private static final HttpClient HTTP = HttpClient.newHttpClient();
 26	    private static String schema;
 27	    private static String url, user, password;
 28	    private static Javalin app;
 29	    private static String base;
 30	
 31	    @BeforeAll
 32	    static void start() throws Exception {
 33	        url = System.getenv("DB_URL");
 34	        user = System.getenv("DB_USER");
 35	        password = System.getenv("DB_PASSWORD");
 36	        Assumptions.assumeTrue(url != null, "DB_URL não definida");
 37	        schema = "teste_" + System.nanoTime();
 38	        try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
 39	            s.execute("CREATE SCHEMA " + schema);
 40	        } catch (Exception e) {
 41	            Assumptions.abort("Banco indisponível: " + e.getMessage());
 42	        }
 43	        String scoped = url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema;
 44	        app = App.build(new Database(scoped, user, password), false).start(0);
 45	        base = "http://localhost:" + app.port();
 46	    }
 47	
 48	    @AfterAll
 49	    static void stop() throws Exception {
 50	        if (app != null) app.stop();
 51	        if (schema != null) {
 52	            try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
 53	                s.execute("DROP SCHEMA " + schema + " CASCADE");
 54	            }
 55	        }
 56	    }
 57	
 58	    private static HttpResponse<String> call(String method, String path, String body) throws Exception {
 59	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
 60	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 61	        return HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
 62	    }
 63	
 64	    private static String reservation(int room, String in, String out, int guests, String plan, String email) {
 65	        return """
 66	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"%s","guestCpf":"11122233344",
 67	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, email, in, out, guests, plan);
 68	    }
 69	
 70	    @Test
 71	    void fullFlow() throws Exception {
 72	        assertEquals(5, JSON.readTree(call("GET", "/rooms", null).body()).size());
 73	
 74	        HttpResponse<String> created = call("POST", "/reservations", reservation(201, "2030-03-10", "2030-03-12", 2, "STANDARD", "carla@example.com"));
 75	        assertEquals(201, created.statusCode());
 76	        JsonNode r = JSON.readTree(created.body());
 77	        long id = r.get("id").asLong();
 78	        assertEquals("PENDING", r.get("status").asText());
 79	        assertTrue(created.body().contains("\"amountPaid\":0.00"));
 80	        assertTrue(r.get("refund").isNull());
 81	        assertTrue(created.body().contains("\"total\":779.80"));
 82	
 83	        assertEquals(409, call("POST", "/reservations", reservation(201, "2030-03-11", "2030-03-13", 2, "STANDARD", "c@example.com")).statusCode());
 84	        assertEquals(422, call("POST", "/reservations", reservation(101, "2030-03-11", "2030-03-13", 3, "STANDARD", "c@example.com")).statusCode());
 85	        assertEquals(404, call("POST", "/reservations", reservation(999, "2030-03-11", "2030-03-13", 1, "STANDARD", "c@example.com")).statusCode());
 86	        assertEquals(400, call("POST", "/reservations", "{nao json").statusCode());
 87	        assertEquals(400, call("POST", "/reservations", reservation(201, "2030-03-12", "2030-03-12", 1, "STANDARD", "c@example.com")).statusCode());
 88	        assertEquals(409, call("GET", "/reservations/" + id + "/document", null).statusCode());
 89	        assertEquals(409, call("POST", "/reservations/" + id + "/check-in", null).statusCode());
 90	
 91	        JsonNode confirmed = JSON.readTree(call("POST", "/reservations/" + id + "/confirmation", null).body());
 92	        assertEquals("CONFIRMED", confirmed.get("status").asText());
 93	        assertEquals(0, new java.math.BigDecimal("779.80").compareTo(confirmed.get("amountPaid").decimalValue()));
 94	
 95	        JsonNode messages = JSON.readTree(call("GET", "/messages", null).body());
 96	        assertEquals(2, messages.size());
 97	        assertEquals("carla@example.com", messages.get(0).get("to").asText());
 98	        assertEquals("SENT", messages.get(0).get("status").asText());
 99	        assertEquals("[Cópia] Reserva confirmada - Pousada Maré Alta", messages.get(1).get("subject").asText());
100	
101	        HttpResponse<String> occupancy = call("GET", "/reports/occupancy?date=2030-03-11", null);
102	        assertTrue(occupancy.headers().firstValue("content-type").orElse("").toLowerCase().contains("text/csv"));
103	        assertTrue(occupancy.body().endsWith("total,1/5\n"));
104	        assertEquals(400, call("GET", "/reports/revenue?month=2030-3", null).statusCode());
105	        assertTrue(call("GET", "/reports/revenue?month=2030-03", null).body().contains("779.80"));
106	
107	        assertEquals(200, call("POST", "/reservations/" + id + "/check-in", null).statusCode());
108	        assertEquals(409, call("POST", "/reservations/" + id + "/cancellation", null).statusCode());
109	        JsonNode receipt = JSON.readTree(call("POST", "/reservations/" + id + "/check-out", null).body());
110	        assertEquals("Comprovante de reserva", receipt.get("title").asText());
111	        assertEquals("DELUXE", receipt.get("roomType").asText());
112	        assertEquals(200, call("GET", "/reservations/" + id + "/document", null).statusCode());
113	        assertEquals(404, call("GET", "/reservations/99999", null).statusCode());
114	    }
115	
116	    @Test
117	    void invalidEmailBlockedAndRefundOnCancel() throws Exception {
118	        JsonNode r = JSON.readTree(call("POST", "/reservations", reservation(301, "2030-05-10", "2030-05-11", 4, "NON_REFUNDABLE", "ana@gmail")).body());
119	        long id = r.get("id").asLong();
120	        call("POST", "/reservations/" + id + "/confirmation", null);
121	        JsonNode cancelled = JSON.readTree(call("POST", "/reservations/" + id + "/cancellation", null).body());
122	        assertEquals(0, cancelled.get("refund").decimalValue().signum());
123	        JsonNode messages = JSON.readTree(call("GET", "/messages", null).body());
124	        boolean blocked = false;
125	        for (JsonNode m : messages) {
126	            if (m.get("to").asText().equals("ana@gmail")) {
127	                assertEquals("BLOCKED", m.get("status").asText());
128	                blocked = true;
129	            }
130	        }
131	        assertTrue(blocked);
132	    }
133	}

